{
  "page": {
    "use": "page/basic",
    "data": {
      "title": "FAQ page",
      "site": "Larkspur Supply Co.",
      "description": "Frequently asked questions about Larkspur Supply Co. membership and rentals.",
      "heading": "FAQ page"
    },
    "slots": {
      "main": [
        {
          "use": "content/prose",
          "key": "intro",
          "data": {
            "html": "<p>Frequently asked questions about Larkspur Supply Co. membership and rentals.</p>"
          }
        },
        {
          "use": "content/faq",
          "key": "faq",
          "data": {
            "items": [
              { "question": "How much does membership cost?", "answer": "<p>A lifetime membership costs $30, paid once.</p>" },
              { "question": "What is the member dividend?", "answer": "<p>Each spring, members get back a share of the profit, based on what they bought the year before. Last year it was 8%.</p>" },
              { "question": "Can I rent gear without being a member?", "answer": "<p>Yes. Members get 20% off rentals.</p>" },
              { "question": "How do I return a rental?", "answer": "<p>Bring it to the rental desk by closing time on the return date. Late returns cost one extra day.</p>" },
              { "question": "Do you repair gear you didn't sell?", "answer": "<p>Yes, we repair any brand. Estimates are free.</p>" },
              { "question": "Can I cancel my membership?", "answer": "<p>Yes. We refund your $30 if you cancel within 30 days.</p>" }
            ]
          }
        },
        {
          "use": "content/prose",
          "key": "contact",
          "data": {
            "html": "<p>Still have questions? <a href=\"/contact\">Contact us</a>.</p>"
          }
        }
      ]
    }
  }
}

